// Original editable illustrations, created for this game; no stock photos.
export function foodImage(id){const key=id==='beans'?'beans-meal':id;return '<img class="food-thumb" src="assets/food/'+key+'.svg" width="56" height="56" alt="" loading="lazy">';}
export function ingredientImage(id){return '<img class="food-thumb" src="assets/food/'+id+'.svg" width="48" height="48" alt="" loading="lazy">';}
